Current WIP patch is bb-main-mdev-9826 663ab8b3fdf4b2dc1b026ae28c5aa7ae2741966f. It has an implementation of CRC32C and XXH32/XXH3 from the xxhash family. Since this is a new feature that does not affect existing tests, I've included the test in the main suite to maximise exposure (e.g. coverage in different archs). I also wrote a test-only patch to set the default algorithm to CRC32C, and among the many test failures caused by this change, some are "real" failures that is not just a relocation of data among partitions or change of SHOW CREATE TABLE output. One such failure is the MDEV-6255 testcase, which can be reproduced at the current WIP patch by applying this diff:

{code:diff}
modified   mysql-test/main/partition_key_algorithm.test
@@ -102,3 +102,31 @@ INSERT INTO t1 VALUES (X'000000000000000000000000C0000280');
 INSERT INTO t1 VALUES (X'00000000000000000000FFFFC0000280');
 select partition_name, table_rows from information_schema.partitions where table_name='t1';
 drop table t1;
+
+--echo ## MDEV-6255 case to test charset/collation
+--echo ### cp1251_ukrainian_ci: 0x20 SPACE is equal to 0x60 GRAVE ACCENT
+CREATE TABLE t1 (a VARCHAR(10) CHARACTER SET cp1251 COLLATE cp1251_ukrainian_ci);
+INSERT INTO t1 VALUES (0x20),(0x60),(0x6060),(0x606060);
+SELECT HEX(a) FROM t1 WHERE a=0x60;
+eval
+ALTER TABLE t1  PARTITION BY KEY $algo (a) PARTITIONS 3;
+SELECT HEX(a) FROM t1 WHERE a=0x60;
+DROP TABLE t1;
+
+--echo ### koi8u_general_ci: 0x20 SPACE is equal to 0x60 GRAVE ACCENT
+CREATE TABLE t1 (a VARCHAR(10) CHARACTER SET koi8u COLLATE koi8u_general_ci);
+INSERT INTO t1 VALUES (0x20),(0x60),(0x6060),(0x606060);
+SELECT HEX(a) FROM t1 WHERE a=0x60;
+eval
+ALTER TABLE t1  PARTITION BY KEY $algo (a) PARTITIONS 3;
+SELECT HEX(a) FROM t1 WHERE a=0x60;
+DROP TABLE t1;
+
+--echo ### cp1250_general_ci: 0x20 SPACE is equal to 0xA0 NO-BREAK SPACE
+CREATE TABLE t1 (a VARCHAR(10) CHARACTER SET cp1250 COLLATE cp1250_general_ci);
+INSERT INTO t1 VALUES (0x20),(0xA0),(0xA0A0),(0xA0A0A0);
+SELECT HEX(a) FROM t1 WHERE a=0xA0;
+eval
+ALTER TABLE t1  PARTITION BY KEY $algo (a) PARTITIONS 3;
+SELECT HEX(a) FROM t1 WHERE a=0xA0;
+DROP TABLE t1;

{code}

This needs to be fixed. 

One possible fix (Option 1) is to adapt the new hash algorithms to various collations. There are about a dozen my_hash_sort_* functions that calculate the hash with considerations to collations (see the list below). They do not have a formal unified interface, but they typically follow these steps:

1. string preprocessing such as skip_trailing_space;
2. iterating over the string and call MY_HASH_ADD on each char (with my_hash_sort_latin1_de being an (the only?) exception by looking up the char in two maps followed by calling MY_HASH_ADD after each lookup)
3. finalising by assigning nr1 and nr2 two values of the mysql5x hash algorithm, where nr1 is the result hash value

{noformat}
./include/m_ctype.h:1764:void my_hash_sort_mb_bin(CHARSET_INFO *cs __attribute__((unused)),
./include/m_ctype.h:1767:void my_hash_sort_mb_nopad_bin(CHARSET_INFO *cs __attribute__((unused)),
./strings/ctype-latin1.c:713:void my_hash_sort_latin1_de(CHARSET_INFO *cs __attribute__((unused)),
./strings/ctype-bin.c:277:void my_hash_sort_bin(CHARSET_INFO *cs __attribute__((unused)),
./strings/ctype-bin.c:295:void my_hash_sort_8bit_bin(CHARSET_INFO *cs __attribute__((unused)),
./strings/ctype-ucs2.c:3079:static void my_hash_sort_ucs2(CHARSET_INFO *cs, const uchar *s, size_t slen,
./strings/ctype-simple.c:361:void my_hash_sort_simple_nopad(CHARSET_INFO *cs,
./strings/ctype-simple.c:378:void my_hash_sort_simple(CHARSET_INFO *cs,
./strings/ctype-utf8.c:529:static void my_hash_sort_utf8mb3_nopad(CHARSET_INFO *cs, const uchar *s, size_t slen,
./strings/ctype-utf8.c:550:static void my_hash_sort_utf8mb3(CHARSET_INFO *cs, const uchar *s, size_t slen,
{noformat}

MY_HASH_ADD is the streaming iterating step hash function that has equivalents in other hash functions. But I feel to generalise these functions might be out of scope of an initial implementation (whether this MDEV is asking for an initial implementation is a different matter).

For an initial implementation perhaps we do this instead: what the current patch is doing is equivalent to using my_hash_sort_bin, which is a vanilla string hashing without any string preprocessing or char lookup or transformation:

{code:c++}
void my_hash_sort_bin(CHARSET_INFO *cs __attribute__((unused)),
                      const uchar *key, size_t len,ulong *nr1, ulong *nr2)
{
  const uchar *end = key + len;
  ulong tmp1= *nr1;
  ulong tmp2= *nr2;
  DBUG_ASSERT(key); /* Avoid UBSAN nullptr-with-offset */

  for (; key < end ; key++)
  {
    MY_HASH_ADD(tmp1, tmp2, (uint) *key);
  }

  *nr1= tmp1;
  *nr2= tmp2;
}
{code}

So in this alternative proposal (Option 2): when creating or altering a table PARTITIONed BY [LINEAR] KEY that would use one of the new hash functions, check that each partition field has my_hash_sort_bin as the mysql5x hash function for the field's collation, and if not, fail the statement with an error.

In this case support for nontrivial collations can be left to a future task. I am trying this first.

... Unfortunately Option 2 (see diff below) mean something as basic as INT is not supported as it has my_charset_latin1 whose hash_sort function is my_hash_sort_simple, so either we need to support that at least, or we only cover date columns.

{code:diff}
modified   sql/sql_partition.cc
@@ -1980,6 +1980,14 @@ bool fix_partition_func(THD *thd, TABLE *table, bool is_create_table_ind)
       List_iterator<const char> it(part_info->part_field_list);
       if (unlikely(handle_list_of_fields(thd, it, table, part_info, FALSE)))
         goto end;
+      if (part_info->key_algorithm > partition_info::KEY_ALGORITHM_55)
+        for (uint i= 0; i < part_info->num_part_fields; i++)
+          if (part_info->part_field_array[i]->sort_charset()->coll->hash_sort != my_hash_sort_bin)
+          {
+            my_error(ER_NOT_SUPPORTED_YET, MYF(0),
+                     "this key algorithm and collation combination");
+            goto end;
+          }
     }
     else
     {

{code}

... And to support INT looks like taking the path of Option 1. Also length may differ: pack_length() for say Field_long, but get_length() for Field_varstring, which also points to building on the existing Hasher class.

... And started a new implementation based on this idea (bb-main-mdev-9826 b41df59c8f3c2b084ddabc101b6098ae2981d5e3) - to be continued.

CC [~serg] and [~bar].

Fleshing out the two options in the previous comment to overcome the collation problem.

*Option 1. Support all collations.*

We pass the key algorithm enum to the Hasher class, which will pass it to the my_hash_sort_* functions as an extra argument, and the latter will dispatch based on this.

I was too overly optimistic about the number of my_hash_sort_* functions that need to be fixed. I verified by arriving at a compilable change (see bb-main-mdev-9826-v2 be4d5a4ceaeb5b8ff540b8b429576aa587c1382a) that are actually 15 "leaf" ones that directly call MY_HASH_ADD rather than calling another my_hash_sort_* function. The ones ending with "bin" can use the full hash function on the buffer after some preprossing. All the others require a streaming hash function that hashes character by character:

- bin - full
- latin1_de - stream
- mb_nopad_bin - full
- simple_nopad - stream
- MY_FUNCTION_NAME(hash_sort) - stream
- MY_FUNCTION_NAME(hash_sort_nopad) - stream
- utf16_nopad - stream
- utf16_nopad_bin - full
- utf32_nopad - stream
- ucs2_nopad - stream
- ucs2_nopad_bin - full
- utf8mb3_nopad - stream
- utf8mb3_general1400_nopad_as_ci - stream
- utf8mb4_nopad - stream
- utf8mb4_general1400_nopad_as_ci - stream

Current WIP change implementing Option 1 is at bb-main-mdev-9826 be4d5a4ceaeb5b8ff540b8b429576aa587c1382a.

*Option 2. Support only non-string types.*

This is similar to how mysql51 hash works (see code snippet below).

With a CREATE/ALTER TABLE statement, reject the statement with an error if PARTITION BY [LINEAR] KEY uses one of the new hash algorithms and the type of any column is MYSQL_TYPE_STRING/VARCHAR.

Then like mysql51 hash, we can force my_hash_sort_bin and we can explicit use pack_length() for length. Unlike mysql51 we can probably do this for MYSQL_TYPE_ENUM/SET too, because there are no real collation issues there (need to verify especially for SET).

One downside of this approach is incompatibility if we want to upgrade to Option 1 in the future. This will be another mysql51/mysql55 situation. This could be especially problematic if the upgrade happens soon.

{code:c++}
    if (use_51_hash)
    {
      switch (field->real_type()) {
      case MYSQL_TYPE_TINY:
//  [... 11 lines elided]
      case MYSQL_TYPE_NEWDATE:
        {
          if (field->is_null())
          {
            hasher.add_null();
            continue;
          }
          /* Force this to my_hash_sort_bin, which was used in 5.1! */
          uint len= field->pack_length();
          hasher.add(&my_charset_bin, field->ptr, len);
          /* Done with this field, continue with next one. */
          continue;
        }
      case MYSQL_TYPE_STRING:
      case MYSQL_TYPE_VARCHAR:
      case MYSQL_TYPE_BIT:
        /* Not affected, same in 5.1 and 5.5 */
        break;
      /*
        ENUM/SET uses my_hash_sort_simple in 5.1 (i.e. my_charset_latin1)
        and my_hash_sort_bin in 5.5!
      ,*/
      case MYSQL_TYPE_ENUM:
      case MYSQL_TYPE_SET:
        {
          if (field->is_null())
          {
            hasher.add_null();
            continue;
          }
          /* Force this to my_hash_sort_bin, which was used in 5.1! */
          uint len= field->pack_length();
          hasher.add(&my_charset_latin1, field->ptr, len);
          continue;
        }
      /* New types in mysql-5.6. */
      case MYSQL_TYPE_DATETIME2:
      case MYSQL_TYPE_TIME2:
      case MYSQL_TYPE_TIMESTAMP2:
        /* Not affected, 5.6+ only! */
        break;

      /* These types should not be allowed for partitioning! */
      case MYSQL_TYPE_NULL:
//  [... 7 lines elided]
      case MYSQL_TYPE_GEOMETRY:
        /* fall through */
      default:
        DBUG_ASSERT(0);                    // New type?
        /* Fall through for default hashing (5.5). */
      }
      /* fall through, use collation based hashing. */
    }
{code}

