fields.description:
Currently prepared statements can only be executed and only a single row may be fetched. This is a severe limitation, in particular when it comes to stored procedures. This limits the support for Dynamic SQL we have and makes migration from, say, Oracle, real difficult. Oracle has support for cursors on Dynamic SQL.

h2. Oracle syntax with SYS_REFCURSOR variables:
{code:sql}
DECLARE
  c SYS_REFCURSOR;
BEGIN
  OPEN c FOR 'SELECT ?' USING 1;
END;
{code}

h2. Standard SQL syntax
Let's support the SQL standard syntax for *{{<dynamic declare cursor>}}*.

The SQL Standard assumes that:
- A cursor first is declared with the FOR clause, which binds the cursor to a prepared statement
- Then the prepared statement gets prepared
- Then the cursor is ready to be opened and fetched using the usual syntax:

{code:sql}
  DECLARE cursor_name FOR prepared_statement_name;    -- <dynamic declare cursor>
  PREPARE prepared_statement_name FROM 'SELECT 1,2';  -- Placeholders are also possible
  OPEN cursor_name;                                   -- USING clause is also possible
{code}


Example:
{code:sql}
CREATE OR REPLACE TABLE t1 (id INT, c1 VARCHAR(10));
INSERT INTO t1 VALUES (10,'c10'),(11,'c11'),(12,'c12');

DELIMITER $$
CREATE OR REPLACE PROCEDURE p1(tab VARCHAR(64), id INTEGER)
BEGIN
  DECLARE no_data BOOL DEFAULT FALSE;
  DECLARE v_c1 VARCHAR(100);
  DECLARE v_id INT;
  DECLARE c1 CURSOR FOR s1;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_data = TRUE;

  PREPARE s1 FROM CONCAT('SELECT id, c1 FROM ', tab, ' WHERE id >= ?');
  OPEN c1 USING id;
  fetch_loop: LOOP
    FETCH c1 INTO v_id, v_c1;
    IF no_data THEN
      LEAVE fetch_loop;
    END IF;
    SELECT v_id, v_c1;
  END LOOP;
  CLOSE c1;
END;
$$
DELIMITER ;
CALL p1('t1',11);
{code}

h2. ROW TYPE OF won't be supported:

As the cursor structure is needed to be known at sp_rcontext creation time, ROW TYPE declarations won't be supported for dynamic cursors:

{code:sql}
CREATE OR REPLACE TABLE t1 (a INT);
INSERT INTO t1 VALUES (1),(2),(3);
DELIMITER $$
CREATE OR REPLACE PROCEDURE p1()
BEGIN
  DECLARE v TEXT;
  DECLARE c CURSOR FOR stmt;
  BEGIN
    DECLARE r ROW TYPE OF c; -- This is wrong
  END;
END;
$$
DELIMITER ;
CALL p1;
{code}


h2. Cursor FOR\-loops won't be supported:

{code:sql}
CREATE OR REPLACE TABLE t1 (a INT);
INSERT INTO t1 VALUES (1),(2),(3);

DELIMITER $$
CREATE OR REPLACE PROCEDURE p1()
BEGIN
  DECLARE c1 CURSOR FOR stmt;
  PREPARE stmt FROM 'SELECT a FROM t1';
  FOR r IN c1
  DO
    INSERT INTO t2 VALUES(r.a);
  END FOR;
END;
$$
DELIMITER ;
CALL p1;
{code}

h2. SYS_REFCURSORs should be supported:
{code:sql}
CREATE OR REPLACE PROCEDURE p1(dynamic_sql VARCHAR) AS
  v1 INT;
  v2 VARCHAR(256);
  c SYS_REFCURSOR;
BEGIN
  OPEN c FOR dynamic_sql;
  FETCH c INTO v1, v2;
  DBMS_OUTPUT.PUT_LINE(v1 || ' ' || v2);
  CLOSE c;
END;
/
CALL p1('SELECT 123, ''v123'' FROM DUAL');
{code}
{noformat}
123 v123
{noformat}

comments.body:
The SQL Standard proposes the following grammar:

{noformat}
<dynamic declare cursor> ::=
  DECLARE <cursor name> <cursor properties> FOR <statement name>

<dynamic open statement> ::= OPEN <dynamic cursor name> [ <input using clause> ]

<dynamic fetch statement> ::=
FETCH [ [ <fetch orientation> ] FROM ] <dynamic cursor name> <output using clause>

<dynamic close statement> ::= CLOSE <dynamic cursor name>
{noformat}

Example:
{noformat}
DECLARE cur CURSOR FOR stmt;
SET query='SELECT a FROM t1';
PREPARE stmt FROM query;
FETCH FROM cur INTO va;
CLOSE cur;
{noformat}

h2. IBM DB2 seems to follow the standard for dynamic cursors:
{code:sql}
CREATE TABLE t0 (a VARCHAR(32), b VARCHAR(32));
CREATE TABLE t1 (a VARCHAR(32), b VARCHAR(32));
INSERT INTO t1 VALUES (10,20);
INSERT INTO t1 VALUES (11,21);

CREATE PROCEDURE p1 (IN p_table_name VARCHAR(128))
BEGIN
  DECLARE dynamic_sql VARCHAR(1000);
  DECLARE v_column1 VARCHAR(50);
  DECLARE v_column2 INT;
  DECLARE end_of_data INT DEFAULT 0;
  DECLARE my_cursor CURSOR FOR stmt1;   
  DECLARE EXIT HANDLER FOR NOT FOUND SET END_OF_DATA = 1;

  SET dynamic_sql = 'SELECT a, b FROM ' || p_table_name;

  PREPARE stmt1 FROM dynamic_sql;

  OPEN my_cursor;

  WHILE (end_of_data = 0)
  DO
    FETCH FROM my_cursor INTO v_column1, v_column2;
    INSERT INTO t0 VALUES('a'||v_column1,'b'||v_column2);
  END WHILE;

  CLOSE my_cursor;
END;

call p1('t1');

SELECT * FROM t0;
{code}
{noformat}
A 	B
a10 	b20
a11 	b21
{noformat}

h2. IBM DB2 - dynamic cursor with a parameter

{code:sql}
CREATE TABLE t0 (a VARCHAR(32), b VARCHAR(32));
CREATE TABLE t1 (a VARCHAR(32), b VARCHAR(32));
INSERT INTO t1 VALUES (10,20);
INSERT INTO t1 VALUES (11,21);
CREATE PROCEDURE p1 (IN p_table_name VARCHAR(128))
BEGIN
  DECLARE dynamic_sql VARCHAR(1000);
  DECLARE v_column1 VARCHAR(50);
  DECLARE v_column2 INT;
  DECLARE end_of_data INT DEFAULT 0;
  DECLARE my_cursor CURSOR FOR stmt1;   
  DECLARE EXIT HANDLER FOR NOT FOUND SET END_OF_DATA = 1;

  SET dynamic_sql = 'SELECT a, b FROM ' || p_table_name || ' WHERE b=?';
  PREPARE stmt1 FROM dynamic_sql;
  OPEN my_cursor USING '20';
  WHILE (end_of_data = 0)
  DO
    FETCH FROM my_cursor INTO v_column1, v_column2;
    INSERT INTO t0 VALUES('a'||v_column1,'b'||v_column2);
  END WHILE;
  CLOSE my_cursor;
END;

call p1('t1');
SELECT * FROM t0;
{code}
{noformat}
A 	B
a10 	b20
{noformat}

h2. Oracle style syntax example:
{code:sql}
CREATE OR REPLACE PROCEDURE p1 (p_parameter IN VARCHAR2) IS
  TYPE cur_typ IS REF CURSOR;
  c_cursor cur_typ; -- Note, this can also be a SYS_REFCURSOR variable
  l_text   VARCHAR2(100);
BEGIN
  OPEN c_cursor FOR 'SELECT :parameter FROM DUAL' USING p_parameter;
  LOOP
    FETCH c_cursor INTO l_text;
    EXIT WHEN c_cursor%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(l_text);
  END LOOP;
  CLOSE c_cursor;
END;
/
call p1('test');
{code}
{noformat}
test
{noformat}

h2. Oracle style, an attempt to use a non-SELECT query raises an error
{code:sql}
CREATE OR REPLACE PROCEDURE p1 (p_parameter IN VARCHAR2) IS
  TYPE cur_typ IS REF CURSOR;
  c_cursor cur_typ;
  l_text   VARCHAR2(100);
BEGIN
  OPEN c_cursor FOR 'UPDATE t1 SET a=:parameter' USING p_parameter;
  LOOP
    FETCH c_cursor INTO l_text;
    EXIT WHEN c_cursor%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(l_text);
  END LOOP;
  CLOSE c_cursor;
END;
/
call p1('test');
{code}
{noformat}
ORA-06539: target of OPEN must be a query ORA-06512: at "SQL_TSWMGPRGZPZYJPBEEJIWYNKAC.P1", line 6
ORA-06512: at line 1
ORA-06512: at "SYS.DBMS_SQL", line 1721
{noformat}

h2. FOR loop for dynamic cursors - won't be supported
Oracle does not support FOR loops over dynamic cursors:
{code:sql}
FOR rec IN sys_refcursor_variable
{code}
So FOR loop for dynamic cursors won't be supported.

