2	DERIVED	t1	range	NULL	grp_id	5	NULL	101	Using index for group-by
3	UNION	t1	ALL	NULL	NULL	NULL	NULL	10000	Using temporary
{code}

Result after "analyze table t1;":
{code:sql}
id	select_type	table	type	possible_keys	key	key_len	ref	rows	Extra
1	PRIMARY	t2	ALL	NULL	NULL	NULL	NULL	5	Using where
1	PRIMARY	<derived2>	ref	key0	key0	5	test.t2.a	2	
2	DERIVED	t1	range	NULL	grp_id	5	NULL	2	Using index for group-by
3	UNION	t1	ALL	NULL	NULL	NULL	NULL	10	Using temporary
{code}

